   /// 当前验证码挑战(需要时加载)。
   CaptchaPayload? _captcha;

   /// 当前验证码请求;焦点回弹或多个兜底路径同时触发时共享同一请求。
   Future<void>? _captchaLoadFuture;
+  int _challengeGeneration = 0;
+  bool _disposed = false;

   /// 当前登录用户名(跨 TOTP 阶段保留)。
   String _pendingUsername = '';

   /// 登录是否进行中(防重复提交)。
@@ -105,23 +107,54 @@ class AuthController extends ChangeNotifier {

   Future<void> _loadCaptcha({
     required bool preservePhaseOnError,
     required bool silentOnError,
   }) async {
+    final generation = _challengeGeneration;
     try {
-      _captcha = await _auth.getCaptcha();
+      final captcha = await _auth.getCaptcha();
+      if (generation != _challengeGeneration) return;
+      _captcha = captcha;
       // 仅清除本方法写入的验证码提示,不覆盖登录流程自身的错误文案。
       if (_error == _captchaLoadError) _error = '';
       notifyListeners();
     } catch (_) {
+      if (generation != _challengeGeneration) return;
       if (silentOnError) return;
       _error = _captchaLoadError;
       if (!preservePhaseOnError) _phase = LoginPhase.failed;
       notifyListeners();
     }
   }

+  /// Leave the current form without carrying its challenge into another mode.
+  /// Clearing staged credentials completes before the next form can submit.
+  Future<void> cancelChallenge() async {
+    if (_busy) return;
+    _busy = true;
+    _challengeGeneration++;
+    _captchaLoadFuture = null;
+    _captcha = null;
+    _pendingUsername = '';
+    _phase = LoginPhase.idle;
+    _error = '';
+    notifyListeners();
+    try {
+      await _tokenStorage.clear();
+    } finally {
+      _busy = false;
+      if (!_disposed) notifyListeners();
+    }
+  }
+
+  @override
+  void dispose() {
+    _disposed = true;
+    _challengeGeneration++;
+    super.dispose();
+  }
+
   /// 密码登录。传 captchaId/captchaCode 时携带验证码。
   Future<void> login({
     required String username,
     required String password,
     String? captchaId,
@@ -222,31 +255,43 @@ class AuthController extends ChangeNotifier {
       _busy = false;
       notifyListeners();
     }
   }

-  /// 注册。
+  /// 注册。locale 由调用方提供当前界面语言,省略时保留服务端兜底。
   Future<String?> register({
     required String username,
     required String email,
     required String password,
     String? captchaId,
     String? captchaCode,
+    String? locale,
   }) async {
     _busy = true;
     _error = '';
     notifyListeners();
     String? messageCode;
     try {
+      // Only this request's New-Token may authenticate the new account.
+      await _tokenStorage.clear();
+      _pendingUsername = '';
       messageCode = (await _auth.register(
         username: username,
         email: email,
         password: password,
         captchaId: captchaId,
         captchaCode: captchaCode,
+        locale: locale,
       )).messageCode;
-      _phase = LoginPhase.idle;
+      final token = await _tokenStorage.read();
+      if (token == null || token.isEmpty) {
+        throw const ApiException(
+          fallbackMessage: 'Account created. Please sign in to continue.',
+          messageCode: 'auth.register.retryLogin',
+        );
+      }
+      await _completeLogin(username: username);
     } on ApiException catch (e) {
       final resolved = _resolveAuthError(
         e,
         fallback: 'Unable to register, please retry',
