diff --git a/apps/mobile/packages/auth/test/auth_controller_test.dart b/apps/mobile/packages/auth/test/auth_controller_test.dart
index 7f82e0222..95717e39a 100644
--- a/apps/mobile/packages/auth/test/auth_controller_test.dart
