+      reduced: GfMotion.reducedOf(context),
+    );
+  }
+
+  bool _onScroll(ScrollNotification notification) {
+    if (!widget.enabled ||
+        notification.depth != 0 ||
+        notification.metrics.axisDirection != AxisDirection.down) {
+      return false;
+    }
