+    controller.overscroll =
+        notification.metrics.minScrollExtent - notification.metrics.pixels;
+    if (notification is ScrollStartNotification) {
+      _tracking =
+          notification.dragDetails != null &&
+          notification.metrics.extentBefore == 0 &&
+          !controller.busy;
