+            ),
+          ),
+          const SizedBox(height: GfSpace.lg),
+          GfText(
+            label,
+            maxLines: 1,
+            overflow: TextOverflow.ellipsis,
+            textAlign: TextAlign.center,
+            style: typography.heading,
