+            builder: (_, _) =>
+                const Scaffold(body: Text('unfinished operation')),
+          ),
+          GoRoute(
+            path: '/settings/account',
+            builder: (_, _) => const SettingsPage(initialSection: 'account'),
+          ),
+        ],
