+        expect(
+          panel.right,
+          lessThanOrEqualTo(
+            tester.view.physicalSize.width - padding.right - 16,
+          ),
+        );
+        expect(panel.top, greaterThanOrEqualTo(padding.top + 16));
+        expect(panel.bottom, lessThanOrEqualTo(740 - padding.bottom - 16));
