+      expect(find.text('候选'), findsOneWidget);
+      scope.notifier.selectClass(detail('110001.01', room: 'A101'), '高等数学');
+      scope.notifier.selectClass(detail('110002.01', room: 'A102'), '大学物理');
+      scope.notifier.addCustomEvent(
+        label: '实验室',
+        day: 3,
+        sections: [3],
+        weeks: [1, 2],
+      );
