+      expect(
+        tester.widget<TextField>(find.byType(TextField)).controller!.text,
+        '高等数学',
+      );
+    }
+  });
+  testWidgets('retained candidates fence previous course context responses', (
+    tester,
+  ) async {
+    final scope = await openTaskFlow(tester);
