+    // The dock's press spring: quick and slightly lively in, calm out.
+    _springTo(1, 520, 0.62);
+  }
+
+  void _move(PointerMoveEvent event) {
+    if (_pointers > 0) _light.value = event.localPosition;
+  }
+
+  void _up(PointerEvent _) {
