+          ) &&
+          !candidate.contains('\uFE0F');
+      final asset = isBareDefaultTextEmoji ? null : twemojiAssetBySequence[key];
       if (asset != null) {
         bestEnd = end + 1;
         bestAsset = asset;
       }
     }

