diff --git a/apps/mobile/packages/core/test/sticker_editing_test.dart b/apps/mobile/packages/core/test/sticker_editing_test.dart
new file mode 100644
index 000000000..f6e989812
--- /dev/null
+++ b/apps/mobile/packages/core/test/sticker_editing_test.dart
@@ -0,0 +1,96 @@
+import 'dart:ui' show TextRange;
+
+import 'package:core/core.dart';
+import 'package:flutter_test/flutter_test.dart';
+
+void main() {
+  group('stickerTokenRanges', () {
+    test(
+      'Markdown excludes code, links and escapes; plain text only escapes',
+      () {
+        const content =
+            '`[:sticker:a:]` [:sticker:b:] [x](/[:sticker:c:]) \\[:sticker:d:]';
+        expect(stickerTokenRanges(content, markdown: true), const [
+          StickerTokenRange(16, 29, 'b'),
+        ]);
+        expect(
+          stickerTokenRanges(content, markdown: false).map((r) => r.name),
+          ['a', 'b', 'c'],
+        );
+      },
+    );
+  });
+
+  group('expandStickerDeletion', () {
+    const text = '你好[:sticker:huaji:]！';
+    test('one backspace after a token removes all of it', () {
+      expect(
+        expandStickerDeletion(text, 18, 19),
+        const TextRange(start: 2, end: 19),
+      );
+    });
+    test('a delete at the token start removes all of it', () {
+      expect(
+        expandStickerDeletion(text, 2, 3),
+        const TextRange(start: 2, end: 19),
+      );
+    });
+    test('half-typed fragments are atomic too', () {
+      expect(
+        expandStickerDeletion('图 [:sticker:na', 13, 14),
+        const TextRange(start: 2, end: 14),
+      );
+      expect(
+        expandStickerDeletion('[:sticker:huaji:', 15, 16),
+        const TextRange(start: 0, end: 16),
+      );
+    });
+    test('plain text keeps single-character deletion', () {
+      expect(
+        expandStickerDeletion(text, 19, 20),
+        const TextRange(start: 19, end: 20),
+      );
+      expect(
+        expandStickerDeletion('你好', 1, 2),
+        const TextRange(start: 1, end: 2),
+      );
+    });
+  });
+
+  test('extractStickerQuery mirrors the web rules', () {
+    expect(
+      extractStickerQuery('看 [:sticker:hu'),
+      const StickerQuery(length: 12, query: 'hu'),
+    );
+    expect(
+      extractStickerQuery('[:sticker:'),
+      const StickerQuery(length: 10, query: ''),
+    );
+    expect(extractStickerQuery('[:sticker:huaji:]'), isNull);
+    expect(extractStickerQuery('[:sticker:hu aji'), isNull);
+    expect(extractStickerQuery(r'\[:sticker:hu'), isNull);
+  });
+
+  test('rankStickerSuggestions orders exact, prefix, then substring', () {
+    final items = [
+      ('u_1', '我的滑稽'),
+      ('huaji', 'huaji'),
+      ('shuai', 'shuai'),
+      ('hug', 'hug'),
+      ('huaji', 'duplicate'),
+    ];
+    List<String> rank(String query, {int limit = 8}) => rankStickerSuggestions(
+      items,
+      query,
+      name: (item) => item.$1,
+      label: (item) => item.$2,
+      limit: limit,
+    ).map((item) => item.$1).toList();
+    expect(rank(''), ['u_1', 'huaji', 'shuai', 'hug']);
+    expect(rank('', limit: 2), ['u_1', 'huaji']);
+    expect(rank('hu'), ['huaji', 'hug', 'shuai']);
+    expect(rank('hug'), ['hug']);
+    expect(rank('我的'), ['u_1']);
+    expect(rank('zzz'), isEmpty);
+  });
+}

diff --git a/apps/mobile/packages/core/test/sticker_embed_test.dart b/apps/mobile/packages/core/test/sticker_embed_test.dart
new file mode 100644
index 000000000..80e07f540
--- /dev/null
+++ b/apps/mobile/packages/core/test/sticker_embed_test.dart
@@ -0,0 +1,91 @@
+import 'package:core/core.dart';
+import 'package:flutter/services.dart';
+import 'package:flutter_quill/flutter_quill.dart';
+import 'package:flutter_test/flutter_test.dart';
+
+List<Object?> embeds(Document document) => [
+  for (final op in document.toDelta().toList())
+    if (op.data is Map) op.data,
+];
+
+void main() {
+  final converter = MarkdownConverter();
+
+  test('prose tokens load as embeds and save back as tokens', () {
+    const markdown = '今天 [:sticker:huaji:] 下课见 [:sticker:doge:]';
+    final document = converter.mdToDocument(markdown);
+    expect(embeds(document), [
+      {stickerEmbedType: 'huaji'},
+      {stickerEmbedType: 'doge'},
+    ]);
+    expect(document.toPlainText(), '今天 ￼ 下课见 ￼\n');
+    expect(converter.documentToMarkdown(document).trim(), markdown);
+  });
+
+  test('code, links, math and escaped tokens stay text', () {
+    const markdown =
+        '`[:sticker:a:]` [x](/u) [:sticker:b:]\n\n'
+        '```\n[:sticker:c:]\n```\n\n'
+        r'$[:sticker:d:]$';
+    final document = converter.mdToDocument(markdown);
+    expect(embeds(document), [
+      {stickerEmbedType: 'b'},
+    ]);
+    final saved = converter.documentToMarkdown(document);
+    for (final name in ['a', 'b', 'c', 'd']) {
+      expect(saved, contains('[:sticker:$name:]'));
+    }
+  });
+
+  test('a backslash typed before a token keeps it literal', () {
+    final document = Document()..insert(0, r'\[:sticker:e:] [:sticker:f:]');
+    expect(documentStickerTokens(document), const [
+      StickerTokenRange(15, 28, 'f'),
+    ]);
+  });
+
+  test('a sticker inside emphasis keeps the emphasis whole', () {
+    const markdown = '**粗体 [:sticker:huaji:] 粗体**';
+    final document = converter.mdToDocument(markdown);
+    expect(embeds(document), [
+      {stickerEmbedType: 'huaji'},
+    ]);
+    expect(converter.documentToMarkdown(document).trim(), markdown);
+  });
+
+  test('typed tokens become embeds and the caret follows', () {
+    final controller = QuillController(
+      document: Document()..insert(0, 'a [:sticker:huaji:] b'),
+      selection: const TextSelection.collapsed(offset: 19),
+    );
+    expect(embedStickerTokensIn(controller), isTrue);
+    expect(embeds(controller.document), [
+      {stickerEmbedType: 'huaji'},
+    ]);
+    expect(controller.document.toPlainText(), 'a ￼ b\n');
+    expect(controller.selection, const TextSelection.collapsed(offset: 3));
+    expect(embedStickerTokensIn(controller), isFalse);
+  });
+
+  test('undo after a typed token returns to the unclosed fragment', () {
+    final controller = QuillController.basic();
+    controller.replaceText(
+      0,
+      0,
+      '[:sticker:huaji:',
+      const TextSelection.collapsed(offset: 16),
+    );
+    // A later keystroke, outside the history merge window of the first.
+    controller.document.history.lastRecorded = 0;
+    controller.replaceText(
+      16,
+      0,
+      ']',
+      const TextSelection.collapsed(offset: 17),
+    );
+    embedStickerTokensIn(controller);
+    expect(controller.document.toPlainText(), '￼\n');
+    controller.undo();
+    expect(controller.document.toPlainText(), '[:sticker:huaji:\n');
+  });
+}

