+        if (state.loading)
+          const GfLoading()
+        else if (state.status == null)
+          GfErrorRetry(
+            message: campusError(l, state.error),
+            onRetry: () =>
+                ref.read(campusControllerProvider.notifier).refresh(),
+          )
+        else
+          const CampusConnection(),
+      ],
+    );
+  }
+}

