+      if (!canEdit) return false;
+      final next = update(state);
+      try {
+        if (scope case final String target) {
+          await _database.writeBatch(
+            target,
+            kTimetableMemoDomain,
+            {key: jsonEncode(encode(next))},
+            generation: _generation,
+            isCurrent: () => mounted,
+          );
+        }
