+  Future<void> _load({String? topic, bool more = false}) async {
+    final nextTopic = topic ?? _topic;
+    final page = more ? _page + 1 : 1;
+    final request = ++_request;
+    setState(() {
+      _loading = true;
+      _error = null;
+      if (!more) _topic = nextTopic;
