+  final String label;
+  final String? collectLabel;
+  final bool collectArmed;
+
+  @override
+  Widget build(BuildContext context) {
+    final colors = GfTheme.colorsOf(context);
+    final reduceMotion = MediaQuery.of(context).disableAnimations;
+    final bubble = MetaData(
+      metaData: const _PeekBubble(),
+      behavior: HitTestBehavior.opaque,
+      child: Container(
+        width: 156,
+        padding: const EdgeInsets.all(10),
+        decoration: BoxDecoration(
+          color: colors.surfaceRaised,
+          borderRadius: BorderRadius.circular(GfRadius.lg),
+          border: Border.all(
+            color: colors.separator,
+            width: gfHairline(context),
+          ),
+          boxShadow: colors.elevation(GfElevation.mid),
+        ),
+        child: Column(
+          mainAxisSize: MainAxisSize.min,
+          children: [
+            IgnorePointer(
+              child: StickerImage(
+                key: ValueKey(item.name),
+                name: item.name,
+                url: item.url,
+                label: label,
+                size: 120,
+                collectible: false,
+                excludeSemantics: true,
+              ),
+            ),
+            const SizedBox(height: 6),
+            GfText(
+              label,
+              maxLines: 1,
+              overflow: TextOverflow.ellipsis,
+              style: TextStyle(fontSize: 12, color: colors.textSecondary),
+            ),
+            if (collectLabel != null) ...[
+              const SizedBox(height: 8),
+              MetaData(
+                metaData: const _PeekCollect(),
+                behavior: HitTestBehavior.opaque,
+                child: AnimatedContainer(
+                  duration: reduceMotion
+                      ? Duration.zero
+                      : const Duration(milliseconds: 120),
+                  curve: Curves.easeOut,
+                  constraints: const BoxConstraints(minHeight: 36),
+                  padding: const EdgeInsets.symmetric(
+                    horizontal: 12,
+                    vertical: 8,
+                  ),
+                  decoration: BoxDecoration(
+                    color: collectArmed ? colors.primary : colors.fill,
+                    borderRadius: BorderRadius.circular(GfRadius.full),
+                  ),
+                  child: Row(
+                    mainAxisSize: MainAxisSize.min,
+                    children: [
+                      GfSymbol(
+                        'bookmark',
+                        size: 16,
+                        color: collectArmed
+                            ? colors.primaryContent
+                            : colors.textPrimary,
+                      ),
+                      const SizedBox(width: 6),
+                      Flexible(
+                        child: GfText(
+                          collectLabel!,
+                          maxLines: 1,
+                          overflow: TextOverflow.ellipsis,
+                          style: TextStyle(
+                            fontSize: 12,
+                            fontWeight: FontWeight.w600,
+                            color: collectArmed
+                                ? colors.primaryContent
+                                : colors.textPrimary,
+                          ),
+                        ),
+                      ),
+                    ],
+                  ),
+                ),
+              ),
+            ],
+          ],
+        ),
+      ),
+    );
+    if (reduceMotion) return bubble;
+    return TweenAnimationBuilder<double>(
