+      await tester.pumpAndSettle();
+      await tester.tap(find.text(l.campusTimetable));
+      await tester.pumpAndSettle();
+      expect(find.text('尚未连接同济身份'), findsOneWidget);
+      expect(find.byKey(const Key('campus-timetable-courses')), findsOneWidget);
