+            ..current = const CampusStatus(
+              enabled: true,
+              binding: null,
+              candidate: null,
+            );
+          await tester.pumpWidget(
+            campusTestApp(
+              repo,
+              locale: Locale(lang),
+              brightness: brightness,
+              scale: 2,
+            ),
