+            highContrast = mode == 0;
+            reducedMotion = mode == 1;
+            accessibleNavigation = mode == 2;
+          });
+          await tester.pumpAndSettle();
+          expect(
+            find.descendant(of: rail, matching: find.byType(BackdropFilter)),
+            findsNothing,
+          );
+          expect(selected, 3);
+        }
+        semantics.dispose();
+        expect(tester.takeException(), isNull);
+      },
+    );
