+    }
+  }
+  store.setConfigCollapsed(false);
+  await store.flush;
+  final container = makeContainer(store, repository: repository ?? _Pk());
+  addTearDown(container.dispose);
+  await tester.pumpWidget(
+    UncontrolledProviderScope(
+      container: container,
+      child: MaterialApp(
+        theme: gfThemeData(brightness),
