+                          decoration: BoxDecoration(
+                            color: colors.error,
+                            shape: BoxShape.circle,
+                          ),
+                        )
+                      : _CountPill(
+                          label: GfBadgedGlyph.labelFor(
+                            _shownCount!,
+                            widget.max,
+                          ),
+                          rollsUp: _rollsUp,
+                          scale: scale,
+                          color: colors.error,
+                          style: _style(colors),
+                        ),
+                ),
+              ),
+            ),
+          ],
+        );
+      },
+    );
+  }
+}
+
+/// A capsule whose digits roll in from below as the count grows and from
+/// above as it shrinks.
+class _CountPill extends StatelessWidget {
+  const _CountPill({
+    required this.label,
+    required this.rollsUp,
+    required this.scale,
+    required this.color,
+    required this.style,
+  });
+
+  final String label;
+  final bool rollsUp;
+  final double scale;
+  final Color color;
+  final TextStyle style;
+
+  @override
