+
+  group('GfFieldRow', () {
+    testWidgets('计数器超限变红', (tester) async {
+      await tester.pumpWidget(
+        gfApp(
+          const GfListSection(
+            children: [GfFieldRow(label: '简介', maxLength: 5)],
+          ),
+        ),
+      );
