+    _scheduled = true;
+    // Never edit the document from inside its own change notification.
+    scheduleMicrotask(() {
+      _scheduled = false;
+      if (!_cancelled) embedStickerTokensIn(controller);
+    });
+  }
+
+  Future<void> cancel() {
+    _cancelled = true;
+    return _subscription.cancel();
+  }
+}

