+        }
+        await tester.pumpWidget(const SizedBox.shrink());
+        await tester.pumpAndSettle();
+        container.dispose();
+        return;
+      }
+      final stamp = DateTime.now().millisecondsSinceEpoch;
+      final legacy = LocalDraft(
+        key: 'legacy-$stamp',
