+                  as Map<String, dynamic>;
+          bodies.add(body);
+          request.response.statusCode = accepted ? 200 : 401;
+          request.response.write(
+            jsonEncode(
+              accepted
+                  ? {
+                      'code': 0,
+                      'result': {
+                        'id': 42,
+                        'content': body['content'],
+                        'renderedContent': '',
+                        'updatedAt': '',
+                      },
+                    }
+                  : {'code': 1, 'messageCode': 'auth.required'},
