+                return signedIn
+                    ? const CurrentUser(id: 1, username: 'synthetic-A')
+                    : null;
+              }),
+            ],
+          );
+          final store = container.read(writingStoreProvider);
+          await store.clearAccount(scope);
+          await tester.pumpWidget(
+            UncontrolledProviderScope(
+              container: container,
+              child: MaterialApp.router(
+                routerConfig: router,
