+        ),
+        GfButton(
+          label: l.commonConfirm,
+          onPressed: () => Navigator.pop(context, true),
+        ),
+      ],
+    ),
+  );
+  if (accepted == true) await preferences.setBool(_privacyKey, true);
+  return accepted == true;
+}
