+        onNotification: (OverscrollIndicatorNotification notification) {
+          if (widget.enabled && notification.leading) {
+            notification.disallowIndicator();
+          }
+          return false;
+        },
+        child: NotificationListener<ScrollNotification>(
+          onNotification: _onScroll,
+          child: widget.child,
+        ),
+      );
