+    expect(defines['YOURTJ_API_BASE_URL'], 'https://dev.yourtj.de');
+    expect(defines['YOURTJ_OIDC_ISSUER'], 'https://dev.yourtj.de/api/oauth');
+    expect(defines['YOURTJ_OIDC_CLIENT_ID'], 'yourtj-mobile');
+
+    AppConfig.validateValues(
