+    expect(
+      WindowReservedRegions.fromMessage({
+        'width': 466,
+        'height': 678,
+        'safeArea': [0, 0, 84, 34],
+        'occlusions': [
+          [0, 0, -1, 190],
+        ],
+      }),
+      isNull,
+    );
+    final parsed = WindowReservedRegions.fromMessage({
+      'width': 466,
+      'height': 678,
+      'safeArea': [0, 0, 84, 34],
+      'occlusions': [
