+        tester.view.viewPadding = safe;
+        addTearDown(tester.view.reset);
+        final reserved = WindowReservedRegions(
+          size: Size(width, 678),
+          safeArea: EdgeInsets.only(
+            left: onLeft ? 84 : 0,
+            right: onLeft ? 0 : 84,
+            bottom: 34,
