+Future<
+  ({
+    ScheduleStoreNotifier notifier,
+    ProviderContainer container,
+    FakePkRepository repository,
+  })
+>
+openTaskFlow(
+  WidgetTester tester, {
+  String locale = 'zh',
+  Brightness brightness = Brightness.light,
+  double width = 390,
+  double scale = 1,
+  bool configured = true,
+}) async {
+  SharedPreferences.setMockInitialValues({});
+  final notifier = ScheduleStoreNotifier();
+  await notifier.ready;
+  if (configured) {
+    await notifier.setMajorSelection(
+      PkMajorSelection(
+        calendarId: 119,
+        grade: 2025,
+        major: 'm1',
+        majorName: '软件工程',
+      ),
+    );
+  }
+  final repository = FakePkRepository(
+    GfApiClient(
+      dio: Dio(),
+      tokenStorage: MemoryTokenStorage(),
+      baseUrl: 'http://fake.local',
+    ),
+  );
+  final container = makeContainer(notifier, repository: repository);
+  addTearDown(container.dispose);
+  await tester.pumpWidget(
+    UncontrolledProviderScope(
+      container: container,
+      child: MaterialApp(
+        locale: Locale(locale),
+        localizationsDelegates: AppLocalizations.localizationsDelegates,
+        supportedLocales: AppLocalizations.supportedLocales,
+        theme: ThemeData(brightness: brightness),
+        builder: (context, child) => MediaQuery(
+          data: MediaQuery.of(
+            context,
+          ).copyWith(textScaler: TextScaler.linear(scale)),
+          child: Center(
+            child: SizedBox(width: width, child: child!),
+          ),
+        ),
+        home: const SchedulePage(),
+      ),
+    ),
+  );
+  await tester.pumpAndSettle();
+  return (notifier: notifier, container: container, repository: repository);
+}
+
