+/// The light under the finger, the opaque press tint and the focus ring.
+class _GlassTouchPainter extends CustomPainter {
+  _GlassTouchPainter({
+    required this.colors,
+    required this.prominent,
+    required this.glass,
+    required this.press,
+    required this.light,
+    required this.origin,
+    required this.focused,
