+          end: Alignment.bottomCenter,
+          stops: const <double>[0, 0.55, 1],
+          colors: <Color>[
+            Colors.white.withValues(alpha: dark ? 0.34 : 0.6),
+            Colors.white.withValues(alpha: dark ? 0.04 : 0.1),
+            Colors.white.withValues(alpha: dark ? 0.14 : 0.26),
