+
+  @override
+  Widget build(BuildContext context) => Navigator(
+    pages: <Page<void>>[MaterialPage<void>(child: home)],
+    onDidRemovePage: (_) {},
+  );
+
+  @override
+  Future<bool> popRoute() async {
+    pops++;
+    return true;
+  }
+
+  @override
+  Future<void> setNewRoutePath(Object configuration) async {}
