+    label: 'Campus',
+    symbol: 'school',
+    selectedSymbol: 'school',
+  ),
+  GfBottomNavigationItem(
+    label: 'Notices',
+    symbol: 'bell',
+    selectedSymbol: 'bell',
+    badge: true,
+    badgeCount: count,
+    badgeSemanticLabel: 'Unread',
