+        glyph: const GfSymbol('bell'),
+        size: 24,
+        visible: true,
+        count: count,
+      ),
+    );
+    final pill = find.byWidgetPredicate(
+      (widget) =>
+          widget is DecoratedBox && widget.decoration is ShapeDecoration,
